Tool response:
Tool: create_prescription
Description: Create Prescription
Parameters:
    {
      "type": "object",
      "properties": {
        "visit_id": {
          "type": "integer",
          "description": "The ID of the video visit",
          "title": "Visit Id"
        },
        "medication_id": {
          "type": "integer",
          "title": "Medication Id"
        },
        "dose": {
          "type": "string",
          "title": "Dose"
        },
        "frequency": {
          "type": "string",
          "title": "Frequency"
        },
        "duration_days": {
          "type": "integer",
          "title": "Duration Days"
        }
      },
      "required": [
        "visit_id",
        "medication_id",
        "dose",
        "frequency",
        "duration_days"
      ]
    }

Tool response:
Tool: create_soap_note
Description: Create Soap Note
Parameters:
    {
      "type": "object",
      "properties": {
        "visit_id": {
          "type": "integer",
          "description": "The ID of the video visit",
          "title": "Visit Id"
        },
        "subjective": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Subjective"
        },
        "objective": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Objective"
        },
        "assessment": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Assessment"
        },
        "plan": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Plan"
        },
        "diagnosis_codes": {
          "anyOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Diagnosis Codes",
          "default": []
        },
        "billing_codes": {
          "anyOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Billing Codes",
          "default": []
        }
      },
      "required": [
        "visit_id"
      ]
    }
